// Stage-change history for /market-stage and /stage-analysis, batch-generated by
// scripts/compute_scan_history.py (data/scans/{market_stage,weinstein}_transitions.json).
// Those two scans list every ticker every day, so instead of "days in scan"
// (lib/scanHistory.ts) each ticker carries its stretches of the same stage.

/** [stage, firstDate, lastDate] - ISO dates, both inclusive. */
export type StageRun = [string, string, string];

export interface StageTransitionTicker {
  ticker: string;
  runs: StageRun[]; // oldest first; a day missing from the scan doesn't end a run
  closeByDate: Record<string, number>; // each run's first day + the ticker's last day
}

export interface StageTransitionData {
  generatedAt: string;
  scan: string;
  dates: string[]; // trading days with a snapshot, ascending (holidays/weekends dropped)
  tickers: StageTransitionTicker[];
}

export interface StageDef {
  name: string;
  /** Higher = better. null = not on the scale (IPO / Unknown): a change to or from it is neither up nor down. */
  rank: number | null;
  /** Fill for the daily strip / legend swatch. */
  color: string;
  /** Classes for the stage badge (same look as the page's "today" table). */
  badgeCls: string;
}
